    h += '<span class="hdr-actions"><button class="sv-icon-btn gtb-left-max-btn" data-panel="scoredetail" title="Maximize"><i class="bi bi-fullscreen"></i></button><i class="bi bi-chevron-down gtb-caret"></i></span></div>';
