    s += '<div style="margin-bottom:8px;font-size:0.55rem;color:var(--gtb-muted);">Enter any NSE F&amp;O symbol (e.g. INFY, TCS, SBIN) or MCX commodity.</div>';

    s += '<div style="display:flex;gap:4px;margin-bottom:10px;">';
