                + '<div class="gtb-fut-row ' + _cCls + '">' + (fres['PLUS']  || '—') + '</div>'
                + '<div class="gtb-fut-row ' + _cCls + '">' + (fres['MINUS'] || '—') + '</div>'
                + '</div>';
